using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
namespace Realmwalker.Authoring {
public static class RealmwalkerRig {
 const string R="Assets/Realmwalker";
 static readonly List<Transform> bones=new List<Transform>();static readonly Dictionary<string,Transform> map=new Dictionary<string,Transform>();
 static Vector3 V(float x,float y,float z)=>new Vector3(x,y,z);
 static Transform Bone(string name,Transform parent,Vector3 p){var t=new GameObject("RW_"+name).transform;t.SetParent(parent);t.position=p;bones.Add(t);map[name]=t;return t;}
 static int Id(string n)=>bones.IndexOf(map[n]);
 static BoneWeight W(string a,string b,float t){t=Mathf.Clamp01(t);return new BoneWeight{boneIndex0=Id(a),weight0=1-t,boneIndex1=Id(b),weight1=t};}
 static BoneWeight Weight(Transform part,Vector3 p){string n=part.name;string side=p.x<0?"Left":"Right";
 if(part.GetComponentsInParent<Transform>().Any(t=>t.name=="Head_FaceAndHair"))return W("Head","Head",0);
 if(n=="Neck")return W("Chest","Head",Mathf.InverseLerp(1.5f,1.62f,p.y));
 if(n.Contains("Cape"))return p.y>1.22f?W("CapeTop","CapeMid",Mathf.InverseLerp(1.5f,1.22f,p.y)):W("CapeMid","CapeEnd",Mathf.InverseLerp(1.22f,.94f,p.y));
 if(n.Contains("Scarf")||n=="QuietAmberInset")return W("Chest","Chest",0);
 if(n.Contains("Pauldron"))return W(side+"UpperArm",side+"UpperArm",0);
 if(n.Contains("SleeveUpper"))return W(side+"UpperArm",side+"LowerArm",Mathf.InverseLerp(1.24f,1.16f,p.y));
 if(n.Contains("SleeveForearm"))return W(side+"LowerArm",side+"Hand",Mathf.InverseLerp(1.01f,.95f,p.y));
 if(n.Contains("Bracer"))return W(side+"LowerArm",side+"LowerArm",0);
 if(n.Contains("Glove"))return W(side+"Hand",side+"Hand",0);
 if(n=="TrouserThigh")return W(side+"UpperLeg",side+"LowerLeg",Mathf.InverseLerp(.65f,.53f,p.y));
 if(n=="TrouserCalf"||n=="KneeGuard"||n=="RuggedBootShaft"||n=="BootStrap"||n=="BootBuckle")return W(side+"LowerLeg",side+"LowerLeg",0);
 if(n=="BootFoot"||n=="BootSole")return W(side+"Foot",side+"Foot",0);
 if(n=="SplitTunicPanel")return W("Hips",side+"UpperLeg",Mathf.InverseLerp(1.04f,.82f,p.y)*.75f);
 if(n=="TailoredTunic"||n=="DiagonalHarness"||n=="HarnessStud"||n=="ChestLeatherYoke")return p.y<1.18f?W("Hips","Spine",Mathf.InverseLerp(1.04f,1.18f,p.y)):W("Spine","Chest",Mathf.InverseLerp(1.18f,1.40f,p.y));
 return W("Hips","Hips",0);}
 static void Naming(){int count=0;foreach(var guid in AssetDatabase.FindAssets("",new[]{R})){var path=AssetDatabase.GUIDToAssetPath(guid);var obj=AssetDatabase.LoadMainAssetAtPath(path);if(obj is Mesh||obj is Material||obj is Avatar){string expected=Path.GetFileNameWithoutExtension(path);if(obj.name!=expected){obj.name=expected;EditorUtility.SetDirty(obj);count++;}}}AssetDatabase.SaveAssets();Debug.Log("R1B naming corrected: "+count);}
 [MenuItem("Tools/Lost Worlds/R1B/Rig Existing Realmwalker")]
 public static void Apply(){Naming();if(File.Exists(R+"/Rig/RealmwalkerHumanoidAvatar.asset"))throw new Exception("Existing rig preserved; use validation, not rebuild.");Directory.CreateDirectory(R+"/Rig/SkinnedMeshes");AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(R+"/Realmwalker_Player.prefab"));PrefabUtility.UnpackPrefabInstance(go,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);bones.Clear();map.Clear();var skeleton=new GameObject("Skeleton").transform;skeleton.SetParent(go.transform,false);
 var hips=Bone("Hips",skeleton,V(0,.96f,0));var spine=Bone("Spine",hips,V(0,1.13f,0));var chest=Bone("Chest",spine,V(0,1.39f,0));var neck=Bone("Neck",chest,V(0,1.54f,0));Bone("Head",neck,V(0,1.62f,0));
 foreach(int s in new[]{-1,1}){string side=s<0?"Left":"Right";var shoulder=Bone(side+"Shoulder",chest,V(s*.16f,1.45f,0));var upper=Bone(side+"UpperArm",shoulder,V(s*.255f,1.44f,0));var lower=Bone(side+"LowerArm",upper,V(s*.38f,1.19f,0));Bone(side+"Hand",lower,V(s*.47f,.98f,.015f));var thigh=Bone(side+"UpperLeg",hips,V(s*.115f,.94f,0));var calf=Bone(side+"LowerLeg",thigh,V(s*.13f,.59f,0));var foot=Bone(side+"Foot",calf,V(s*.135f,.15f,0));Bone(side+"Toes",foot,V(s*.135f,.07f,.17f));}
 var cap=Bone("CapeTop",chest,V(0,1.48f,-.14f));cap=Bone("CapeMid",cap,V(0,1.22f,-.18f));Bone("CapeEnd",cap,V(0,.94f,-.22f));
 foreach(var f in go.GetComponentsInChildren<MeshFilter>()){var t=f.transform;var material=f.GetComponent<MeshRenderer>().sharedMaterials;var mesh=Object.Instantiate(f.sharedMesh);mesh.name=f.sharedMesh.name+"_Skin";mesh.bindposes=bones.Select(b=>b.worldToLocalMatrix*t.localToWorldMatrix).ToArray();mesh.boneWeights=mesh.vertices.Select(p=>Weight(t,t.TransformPoint(p))).ToArray();string skinPath=R+"/Rig/SkinnedMeshes/"+mesh.name+".asset";if(File.Exists(skinPath)){Object.DestroyImmediate(mesh);mesh=AssetDatabase.LoadAssetAtPath<Mesh>(skinPath);}else AssetDatabase.CreateAsset(mesh,skinPath);Object.DestroyImmediate(f.GetComponent<MeshRenderer>());Object.DestroyImmediate(f);var sm=t.gameObject.AddComponent<SkinnedMeshRenderer>();sm.sharedMesh=mesh;sm.sharedMaterials=material;sm.bones=bones.ToArray();sm.rootBone=hips;sm.localBounds=new Bounds(t.InverseTransformPoint(V(0,1,0)),Vector3.one*4);sm.updateWhenOffscreen=true;}
 var neutral=bones.Select(b=>b.localRotation).ToArray();foreach(int s in new[]{-1,1}){string side=s<0?"Left":"Right";var arm=map[side+"UpperArm"];arm.rotation=Quaternion.FromToRotation(map[side+"LowerArm"].position-arm.position,Vector3.right*s)*arm.rotation;var forearm=map[side+"LowerArm"];forearm.rotation=Quaternion.FromToRotation(map[side+"Hand"].position-forearm.position,Vector3.right*s)*forearm.rotation;}
 var human=map.Keys.Where(n=>HumanTrait.BoneName.Contains(n)).Select(n=>new HumanBone{boneName=map[n].name,humanName=n,limit=new HumanLimit{useDefaultValues=true}}).ToArray();
 // Unity human names contain spaces; map canonical enum bone names explicitly.
 human=map.Keys.Where(n=>Enum.TryParse<HumanBodyBones>(n,out var b)&&b!=HumanBodyBones.LastBone).Select(n=>new HumanBone{boneName=map[n].name,humanName=HumanTrait.BoneName[(int)Enum.Parse<HumanBodyBones>(n)],limit=new HumanLimit{useDefaultValues=true}}).ToArray();
 var desc=new HumanDescription{human=human,skeleton=new[]{go.transform,skeleton}.Concat(bones).Select(t=>new SkeletonBone{name=t.name,position=t.localPosition,rotation=t.localRotation,scale=t.localScale}).ToArray(),armStretch=.05f,legStretch=.05f,upperArmTwist=.5f,lowerArmTwist=.5f,upperLegTwist=.5f,lowerLegTwist=.5f,feetSpacing=0,hasTranslationDoF=false};var avatar=AvatarBuilder.BuildHumanAvatar(go,desc);avatar.name="RealmwalkerHumanoidAvatar";if(!avatar.isValid||!avatar.isHuman)throw new Exception("Unity rejected generated Humanoid Avatar");AssetDatabase.CreateAsset(avatar,R+"/Rig/RealmwalkerHumanoidAvatar.asset");for(int i=0;i<bones.Count;i++)bones[i].localRotation=neutral[i];
 var animator=go.AddComponent<Animator>();animator.avatar=avatar;animator.applyRootMotion=false;var ctrl=AnimatorController.CreateAnimatorControllerAtPath(R+"/Rig/RealmwalkerAnimator.controller");ctrl.layers[0].stateMachine.AddState("AwaitingAnimationClips");animator.runtimeAnimatorController=ctrl;
 PrefabUtility.SaveAsPrefabAsset(go,R+"/Realmwalker_Player.prefab");AssetDatabase.SaveAssets();Debug.Log("R1B rig saved; validating saved preview.");Validate();}
 [MenuItem("Tools/Lost Worlds/R1B/Validate Rig")]
 public static void Validate(){Naming();EditorSceneManager.OpenScene(R+"/Preview/Realmwalker_Preview.unity");var go=GameObject.Find("Realmwalker_Player");var animator=go.GetComponent<Animator>();if(animator==null||!animator.avatar.isValid||!animator.avatar.isHuman)throw new Exception("Invalid saved avatar");int count=0;float error=0;foreach(var sm in go.GetComponentsInChildren<SkinnedMeshRenderer>()){var m=sm.sharedMesh;if(m==null||sm.bones.Any(b=>b==null)||m.bindposes.Length!=sm.bones.Length||sm.sharedMaterials.Any(x=>x==null))throw new Exception("Skin reference missing");foreach(var w in m.boneWeights)if(Mathf.Abs(w.weight0+w.weight1+w.weight2+w.weight3-1)>.0001f)throw new Exception("Unnormalised weights");var baked=new Mesh();sm.BakeMesh(baked);var v=baked.vertices;var original=m.vertices;for(int i=0;i<v.Length;i++)error=Mathf.Max(error,Vector3.Distance(v[i],original[i]));Object.DestroyImmediate(baked);count++;}if(error>.001f)throw new Exception("Bind pose appearance changed: "+error);
 var transforms=go.GetComponentsInChildren<Transform>();var savedRotations=transforms.Select(t=>t.localRotation).ToArray();var savedPositions=transforms.Select(t=>t.localPosition).ToArray();var handler=new HumanPoseHandler(animator.avatar,go.transform);var pose=new HumanPose();handler.GetHumanPose(ref pose);pose.muscles[0]=.15f;handler.SetHumanPose(ref pose);var roundtrip=new HumanPose();handler.GetHumanPose(ref roundtrip);if(Mathf.Abs(roundtrip.muscles[0]-.15f)>.03f)throw new Exception("Humanoid muscle round-trip failed");handler.Dispose();for(int i=0;i<transforms.Length;i++){transforms[i].localRotation=savedRotations[i];transforms[i].localPosition=savedPositions[i];}
 var bonesByName=go.GetComponentsInChildren<Transform>().Where(t=>t.parent!=null&&t.GetComponentsInParent<Transform>().Any(p=>p.name=="Skeleton")).ToDictionary(t=>t.name.Replace("RW_",""),t=>t);var rest=bonesByName.ToDictionary(p=>p.Key,p=>p.Value.localRotation);
 foreach(string name in new[]{"LeftLowerArm","RightLowerArm"})bonesByName[name].localRotation*=Quaternion.Euler(-45,0,0);foreach(string name in new[]{"LeftLowerLeg","RightLowerLeg"})bonesByName[name].localRotation*=Quaternion.Euler(35,0,0);bonesByName["LeftUpperLeg"].localRotation*=Quaternion.Euler(-25,0,0);bonesByName["RightUpperLeg"].localRotation*=Quaternion.Euler(15,0,0);bonesByName["LeftUpperArm"].localRotation*=Quaternion.Euler(-20,0,0);bonesByName["Head"].localRotation*=Quaternion.Euler(0,20,0);bonesByName["Spine"].localRotation*=Quaternion.Euler(8,0,0);bonesByName["CapeMid"].localRotation*=Quaternion.Euler(-12,0,0);
 foreach(var sm in go.GetComponentsInChildren<SkinnedMeshRenderer>()){var baked=new Mesh();sm.BakeMesh(baked);if(baked.vertices.Any(v=>!float.IsFinite(v.x)||!float.IsFinite(v.y)||!float.IsFinite(v.z)))throw new Exception("Nonfinite posed geometry");Object.DestroyImmediate(baked);}Capture(go,"RigPose");foreach(var p in rest)bonesByName[p.Key].localRotation=p.Value;Capture(go,"RigRest");
 Debug.Log("R1B PASS: valid Unity Humanoid Avatar, HumanPose round-trip, "+count+" weighted mesh parts, bind error "+error+", posed finite geometry and references valid.");File.WriteAllText(R+"/Validation/RigResult.txt","Unity Humanoid Avatar valid/isHuman; HumanPose round-trip passed. "+count+" skins; bind error "+error+". Joint pose preview baked/rendered. No animation clips/locomotion tested.\n");}
 static void Capture(GameObject go,string name){var camera=GameObject.Find("PreviewCamera_Only").GetComponent<Camera>();var type=typeof(RealmwalkerBuilder);var method=type.GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);method.Invoke(null,new object[]{camera});foreach(var view in new[]{"Front","Side","Rear","ThreeQuarter"})File.Copy(R+"/Preview/"+view+".png",R+"/Preview/"+name+"_"+view+".png",true);}
 public static void FinishBatch()=>EditorApplication.delayCall+=()=>{try{var go=PrefabUtility.LoadPrefabContents(R+"/Realmwalker_Player.prefab");bones.Clear();map.Clear();var first=go.GetComponentInChildren<SkinnedMeshRenderer>();bones.AddRange(first.bones);foreach(var b in bones)map[b.name.Replace("RW_","")]=b;foreach(var sm in go.GetComponentsInChildren<SkinnedMeshRenderer>()){sm.sharedMesh.boneWeights=sm.sharedMesh.vertices.Select(v=>Weight(sm.transform,sm.transform.TransformPoint(v))).ToArray();EditorUtility.SetDirty(sm.sharedMesh);}AssetDatabase.SaveAssets();PrefabUtility.UnloadPrefabContents(go);Validate();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}};
 public static void Batch()=>EditorApplication.delayCall+=()=>{try{Apply();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}};
}}
